import { describe, it, expect, vi, beforeEach } from "vitest";
import { render, screen, waitFor, fireEvent, within } from "@testing-library/react";
import { MemoryWorkspace } from "@/features/memory/MemoryWorkspace";

const bsc = vi.hoisted(() => vi.fn());
// A PARTIAL mock, not a replacement. This workspace renders through `Screen`/`usePageTabs`, which
// pull in the app store — and the store imports `bscJson` from this same module. A whole-module mock
// therefore breaks the store's own import rather than this component's, and reports as an unhandled
// rejection from a file that never mentions the store.
vi.mock("@/shared/lib/core/bsc", async (importOriginal) => ({
  ...(await importOriginal<typeof import("@/shared/lib/core/bsc")>()),
  bsc,
}));

const row = (over: Record<string, unknown> = {}) => ({
  id: "1788838726372414613",
  text: "the gate records its own evidence",
  tags: ["gate"],
  created_at_ms: Date.now(),
  status: "open",
  horizon: "now",
  kind: "lesson",
  links: [],
  ...over,
});

/** Open a kind page. The workspace opens on GRAPH, so a list assertion has to navigate there first —
 *  by clicking the tab, which is also how a person gets there.
 *
 *  Scoped to the TABSTRIP on purpose: once a page is open its label is also the heading, so a bare
 *  `findByText` matches two elements and fails on the ambiguity rather than on the behaviour. */
async function openPage(label: string) {
  const strip = document.querySelector(".tabstrip") as HTMLElement;
  const tab = await within(strip).findByText(label);
  fireEvent.click(tab);
}

beforeEach(() => {
  bsc.mockReset();
});

describe("MemoryWorkspace", () => {
  it("reads the GLOBAL store — a null project key, like `bsc skill`", async () => {
    bsc.mockResolvedValue(JSON.stringify([]));
    render(<MemoryWorkspace />);
    await waitFor(() => expect(bsc).toHaveBeenCalled());
    // The payload, not just the call: a memory about the gate is not owned by whichever project
    // happens to be open, so passing a project key here would scope the store wrongly.
    expect(bsc).toHaveBeenCalledWith(null, ["memory", "list", "--json"]);
  });

  it("opens on the GRAPH page — the edges are the point, and a list cannot show them", async () => {
    bsc.mockResolvedValue(JSON.stringify([row({ links: [{ ref: "bsc-mem--cli.rs", rel: "about" }] })]));
    render(<MemoryWorkspace />);
    // The toolbar stat is assembled from several JSX expressions, so it is read as the element's
    // textContent rather than matched as one text node — a matcher that cannot span elements would
    // fail here on the markup rather than on the count.
    await waitFor(() => expect(document.querySelector(".mem-graph-stat")).toBeTruthy());
    // TWO nodes for one memory: the memory itself and the record STUB it points at. That is the
    // claim "everything is a node" made countable.
    expect(document.querySelector(".mem-graph-stat")!.textContent).toContain("2 nodes");
    expect(document.querySelector(".mem-graph-stat")!.textContent).toContain("1 edge");
    // The edge's relationship is drawn as a LABEL on the line, not left as a bare connection.
    expect(screen.getByText("about")).toBeTruthy();
    // Two nodes: the memory, and the record STUB it points at — everything is a node.
    expect(document.querySelectorAll(".mem-node")).toHaveLength(2);
  });

  it("renders a memory's text, tags and every typed edge as a chip on its kind page", async () => {
    bsc.mockResolvedValue(
      JSON.stringify([row({ links: [{ ref: "bsc-mem--cli.rs", rel: "about" }, { ref: "feature:auth", rel: "because" }] })]),
    );
    render(<MemoryWorkspace />);
    await openPage("Lessons");
    expect(await screen.findByText("the gate records its own evidence")).toBeTruthy();
    expect(screen.getByText("#gate")).toBeTruthy();
    // BOTH halves of each edge are text. This is the accessibility guard: `about` and `contradicts`
    // are opposite claims about one target, so neither may be carried by colour alone.
    expect(screen.getByText("about")).toBeTruthy();
    expect(screen.getByText("bsc-mem--cli.rs")).toBeTruthy();
    expect(screen.getByText("because")).toBeTruthy();
    // A prefixed target renders its TYPE and its readable half, not the raw `feature:auth`.
    expect(screen.getByText("feature")).toBeTruthy();
    expect(screen.getByText("auth")).toBeTruthy();
  });

  it("puts each memory only on its own kind page", async () => {
    bsc.mockResolvedValue(
      JSON.stringify([
        row({ id: "1788838726372414613", text: "a rule we learned", kind: "lesson" }),
        row({ id: "1788838726372414614", text: "a decision we took", kind: "highlight" }),
      ]),
    );
    render(<MemoryWorkspace />);
    await openPage("Lessons");
    expect(await screen.findByText("a rule we learned")).toBeTruthy();
    expect(screen.queryByText("a decision we took")).toBeNull();
    await openPage("Highlights");
    expect(await screen.findByText("a decision we took")).toBeTruthy();
    expect(screen.queryByText("a rule we learned")).toBeNull();
  });

  it("names the unclassified count in the footer — a memory with no kind is where nobody looks", async () => {
    bsc.mockResolvedValue(
      JSON.stringify([row({ kind: "note" }), row({ id: "1788838726372414615", kind: "lesson" })]),
    );
    render(<MemoryWorkspace />);
    expect(await screen.findByText("1 unclassified")).toBeTruthy();
  });

  it("surfaces a read failure as the real error — never as an empty store", async () => {
    bsc.mockRejectedValue(new Error("Cannot read properties of undefined (reading 'invoke')"));
    render(<MemoryWorkspace />);
    expect(await screen.findByRole("alert")).toBeTruthy();
    expect(screen.getByText(/Cannot read properties of undefined/)).toBeTruthy();
    // The opposite fact must NOT also be on screen: "could not be read" and "nothing remembered"
    // are contradictory claims, and showing both is how a broken store reads as an empty one.
    expect(screen.queryByText("Nothing remembered yet")).toBeNull();
  });

  it("names the capture command when the store is empty, so the screen is not a dead end", async () => {
    bsc.mockResolvedValue("[]");
    render(<MemoryWorkspace />);
    expect(await screen.findByText("Nothing remembered yet")).toBeTruthy();
    expect(screen.getByText(/bsc memory add/)).toBeTruthy();
  });

  it("reports how many memories AND how many edges — a pile is not a graph", async () => {
    bsc.mockResolvedValue(
      JSON.stringify([row({ links: [{ ref: "a.rs", rel: "about" }] }), row({ id: "1788838726372414614" })]),
    );
    render(<MemoryWorkspace />);
    expect(await screen.findByText("2 memories · 1 edge")).toBeTruthy();
  });
});

