// The Memory workspace — the window onto the session-memory store (`bsc memory`).
//
// It answers the question this repo kept losing: WHAT DO WE KNOW, and what is it about? A session
// generates findings, decisions, lessons and parked threads that have no plan item and no code task,
// and until `bsc memory` they evaporated when the terminal closed. The store catches them; this is
// where a person reads them without opening a shell.
//
// EVERYTHING IS A NODE. A memory carries typed edges (`about`, `because`, `supersedes`, `lesson-of`,
// …) to whatever it relates to — a code record, a FEATURE, a SESSION, a plan ref, another memory — so
// the first page is the GRAPH, and the kind pages are the readable index into it.
//
// THE PAGE AXIS IS KIND, NOT HORIZON, and that is the decision worth keeping. The kinds have
// different provenance and different lifecycles: a lesson comes from a session getting something
// wrong, a highlight from a conversation that must persist indefinitely, a record note from a comment
// inside code, an ambient capture from the always-on ear. Horizon (`now`/`future`) was the first cut
// and it was the model's facet rather than the reader's — two readings of one pile. It survives as a
// filter within a page, which is where it belongs: a highlight can be a hope, a lesson never is.
//
// `note` is a QUEUE, not a category — the kind an unclassified memory reads as, so that omitting
// `--kind` never mislabels one. Same for an edgeless memory: it used to have its own tab, and the
// graph shows it better, as a node visibly floating with nothing reaching it.
//
// EVERY WRITE GOES THROUGH `bsc memory`, not through a UI-only path. `add`/`link`/`horizon`/`done`
// already exist as verbs a session runs, and a capability only the UI has is the bug this project
// keeps correcting — so the footer TEACHES the command rather than replacing it.
import { useCallback, useEffect, useMemo, useState } from "react";
import { Brain, RefreshCw } from "lucide-react";
import { Box } from "@/shared/ui/layout/Box";
import { Row } from "@/shared/ui/layout/Row";
import { Stack } from "@/shared/ui/layout/Stack";
import { Text } from "@/shared/ui/typography/Text";
import { Button } from "@/shared/ui/controls/Button";
import { EmptyState } from "@/shared/ui/feedback/EmptyState";
import { Screen } from "@/shared/ui/layouts/Screen";
import { usePageTabs } from "@/shared/hooks/usePageTabs";
import type { TabItem } from "@/shared/ui/layouts/TabBar";
import { bsc } from "@/shared/lib/core/bsc";
import { MemoryGraphView } from "@/features/memory/MemoryGraphView";
import {
  parseMemories, sortMemories, selectTab, searchMemories, summarize, linkKind, targetLabel,
  relativeAge, MEMORY_TABS, TAB_LABEL, TAB_BLURB, KIND_META,
  type MemoryEntry, type MemoryLink, type MemoryTab,
} from "@/features/memory/lib/memory";

/** The command that captures one — shown in the empty state and the footer, because a screen that
 *  reports an empty store without saying how to fill it is a dead end. */
const CAPTURE_CMD = `bsc memory add "<what you learned>" --kind lesson --link about:<record-id>`;

function LinkChip({ link }: { link: MemoryLink }) {
  const kind = linkKind(link.ref);
  // The relationship is rendered as TEXT, never as colour alone: `about` and `contradicts` are
  // opposite claims about the same target, and a reader who cannot tell two tones apart would see
  // one chip. The kind rides a data attribute so the CSS has one rule per kind, not per rel.
  return (
    <Text as="span" className="mem-chip" data-kind={kind} title={`${link.rel} → ${link.ref} (${kind})`}>
      <span className="mem-chip-rel">{link.rel}</span>
      <span className="mem-chip-kind">{kind}</span>
      <span className="mem-chip-ref mono">{targetLabel(link.ref)}</span>
    </Text>
  );
}

function MemoryRow({ memory, now }: { memory: MemoryEntry; now: number }) {
  return (
    <li className="mem-row" data-horizon={memory.horizon} data-status={memory.status} data-kind={memory.kind}>
      <Stack gap={4} className="mem-body">
        <Text as="p" className="mem-text">{memory.text}</Text>
        <Row gap="xs" wrap align="center" className="mem-meta">
          {/* The kind is on the row as TEXT even inside its own page, because the Graph page mixes
              every kind and a row there must still say what it is. */}
          <Text as="span" className="mem-kind">{KIND_META[memory.kind].label.replace(/s$/, "")}</Text>
          <Text as="span" mono className="mem-age">{relativeAge(memory.createdAtMs, now)}</Text>
          {memory.horizon === "future" && <Text as="span" className="mem-horizon">future</Text>}
          {memory.status === "done" && <Text as="span" className="mem-done">done</Text>}
          {memory.tags.map((t) => (
            <Text as="span" key={t} mono className="mem-tag">#{t}</Text>
          ))}
        </Row>
        {memory.links.length > 0 && (
          <Row gap="xs" wrap align="center" className="mem-links">
            {memory.links.map((l) => (
              <LinkChip key={`${l.rel}:${l.ref}`} link={l} />
            ))}
          </Row>
        )}
      </Stack>
    </li>
  );
}

/** The Memory rail Workspace. */
export function MemoryWorkspace() {
  const [memories, setMemories] = useState<MemoryEntry[]>([]);
  const [error, setError] = useState<string | null>(null);
  // `loaded` rather than `loading`: the empty state and the still-fetching state look identical
  // otherwise, and flashing "nothing remembered" before the first response lands reads as data loss.
  const [loaded, setLoaded] = useState(false);
  const [query, setQuery] = useState("");
  const [now, setNow] = useState(() => Date.now());

  const load = useCallback(async () => {
    try {
      // The memory store is GLOBAL, not per-project — a lesson about the gate is not owned by
      // whichever project happens to be open — so the bridge's project key is null, as for `bsc skill`.
      const raw = await bsc(null, ["memory", "list", "--json"]);
      // Every setState below happens AFTER the await; a synchronous one would run during the
      // effect's own pass, which is what `react-hooks/set-state-in-effect` exists to prevent.
      setMemories(parseMemories(raw));
      setNow(Date.now());
      setError(null);
    } catch (e) {
      // Surfaced, never swallowed into an empty list: "the store could not be read" and "the store
      // is empty" are opposite facts, and this screen exists to say truthfully which one holds.
      setError(e instanceof Error ? e.message : String(e));
    } finally {
      setLoaded(true);
    }
  }, []);

  useEffect(() => {
    void load();
  }, [load]);

  const all = useMemo(() => sortMemories(memories), [memories]);
  const summary = useMemo(() => summarize(all), [all]);

  const defs: TabItem[] = useMemo(
    () =>
      MEMORY_TABS.map((id) => ({
        id,
        label: TAB_LABEL[id],
        // The count decides whether the page is worth opening at all — an Unclassified tab reading 0
        // is the goal state, and worth seeing from outside.
        count: selectTab(all, id).length,
      })),
    [all],
  );
  const pages = usePageTabs("memory", defs);
  const tab = (MEMORY_TABS.find((t) => t === pages.activeId) ?? "graph") as MemoryTab;
  const rows = useMemo(() => searchMemories(selectTab(all, tab), query), [all, tab, query]);

  return (
    <Screen
      tabs={pages.tabs}
      active={pages.activeId}
      onSelect={pages.select}
      onReorder={pages.reorder}
      className="mem-workspace"
      bodyClassName="mem-body-wrap"
    >
      <Stack gap="md" className="mem-screen">
        <Row align="start" justify="between" gap="md" wrap className="mem-head">
          <Stack gap={0}>
            <h2 className="mem-title">{TAB_LABEL[tab]}</h2>
            <p className="mem-sub">{TAB_BLURB[tab]}</p>
          </Stack>
          <Row align="center" gap="sm" className="mem-head-right">
            {loaded && !error && (
              // Both numbers, because they are different claims: how much we remember, and how much
              // of it is connected. A store with many memories and no edges is a pile, not a graph.
              <Text as="span" mono className="mem-count">
                {summary.total} memor{summary.total === 1 ? "y" : "ies"} · {summary.edges} edge
                {summary.edges === 1 ? "" : "s"}
              </Text>
            )}
            <input
              className="mem-search mono"
              type="search"
              value={query}
              placeholder="search text, tags, edges"
              aria-label="Search memories"
              onChange={(e) => setQuery(e.target.value)}
            />
            <Button size="sm" className="mem-refresh" onClick={() => void load()} title="Re-read the memory store">
              <RefreshCw size={14} />
              Refresh
            </Button>
          </Row>
        </Row>

        {error && (
          <Stack gap="xs" className="mem-error" role="alert">
            <strong>The memory store could not be read.</strong>
            <Text as="span" mono>{error}</Text>
          </Stack>
        )}

        {!error && loaded && all.length === 0 && (
          <EmptyState
            icon={<Brain size={20} />}
            title="Nothing remembered yet"
            description="Capture what a session learns but has no plan item for — a finding, a decision, a lesson, a parked thread. Link it to the record or plan ref it is about, and it becomes traversable rather than a note nobody finds again."
            extra={<code className="mono mem-cmd">{CAPTURE_CMD}</code>}
          />
        )}

        {!error && loaded && all.length > 0 && rows.length === 0 && (
          <EmptyState
            icon={<Brain size={20} />}
            title={query.trim() ? "Nothing matches that search" : `Nothing under ${TAB_LABEL[tab]}`}
            description={
              query.trim()
                ? "The store is not empty — this query narrowed it to nothing. Clear the search to see the page again."
                : TAB_BLURB[tab]
            }
          />
        )}

        {/* The GRAPH page renders the canvas; every other page is the readable list for its kind.
            The search box narrows BOTH — a filtered graph is the useful one. */}
        {!error && tab === "graph" && rows.length > 0 && <MemoryGraphView memories={rows} />}

        {!error && tab !== "graph" && rows.length > 0 && (
          <Box as="ul" className="mem-list">
            {rows.map((m) => (
              <MemoryRow key={m.id} memory={m} now={now} />
            ))}
          </Box>
        )}

        {!error && loaded && all.length > 0 && (
          <p className="mem-foot hint">
            Capture with <code className="mono">bsc memory add --kind &lt;kind&gt;</code>, classify one with{" "}
            <code className="mono">bsc memory kind &lt;id&gt; &lt;kind&gt;</code>, connect it with{" "}
            <code className="mono">bsc memory link &lt;id&gt; &lt;rel&gt; &lt;ref&gt;</code>, and ask what we
            remember about anything with <code className="mono">bsc memory list --link &lt;ref&gt;</code>.
            {summary.byKind.note > 0 && (
              <>
                {" "}
                <strong>{summary.byKind.note} unclassified</strong> — a memory with no kind appears where
                nobody looks for it.
              </>
            )}
          </p>
        )}
      </Stack>
    </Screen>
  );
}
